package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.Bundle;import android.text.InputType;import android.widget.*;import java.io.*;import java.util.*;
public final class RecorderLibraryActivity extends LeoActivity {
 private int filter,sort,generation;private String query="";
 protected void onCreate(Bundle b){super.onCreate(b);load();}
 private Set<String> favorites(){return getSharedPreferences("recorder",0).getStringSet("favorites",Collections.<String>emptySet());}
 static boolean accepts(int filter,long modified,long now,boolean favorite){if(filter==3)return favorite;if(filter==2)return modified>=now-7L*86400000;Calendar day=Calendar.getInstance();day.setTimeInMillis(now);day.set(Calendar.HOUR_OF_DAY,0);day.set(Calendar.MINUTE,0);day.set(Calendar.SECOND,0);day.set(Calendar.MILLISECOND,0);long from=day.getTimeInMillis();day.add(Calendar.DATE,1);return filter!=1||modified>=from&&modified<day.getTimeInMillis();}
 private void load(){final int token=++generation,filterSnapshot=filter,sortSnapshot=sort;final String querySnapshot=query;final Set<String> favoriteSnapshot=new HashSet<String>(favorites());begin(L.t("Înregistrări Leo"));root.addView(text(L.t("Se încarcă…"),16));footer("","",L.t("Înapoi"));worker.execute(new Runnable(){public void run(){final ArrayList<File> files=new ArrayList<File>();long now=System.currentTimeMillis();for(File directory:RecordingLocations.folders(RecorderLibraryActivity.this).values()){File[] all=directory.listFiles();if(all==null)continue;for(File f:all)try{if(files.size()>=500)break;if(f.isFile()&&f.getName().endsWith(".m4a")&&LeoFileProvider.inside(directory,f)&&accepts(filterSnapshot,f.lastModified(),now,favoriteSnapshot.contains(f.getCanonicalPath()))&&GlobalSearchActivity.matches(f.getName(),querySnapshot))files.add(f);}catch(IOException ignored){}}Collections.sort(files,new Comparator<File>(){public int compare(File a,File b){return sortSnapshot==1?a.getName().compareToIgnoreCase(b.getName()):Long.compare(b.lastModified(),a.lastModified());}});ui(new Runnable(){public void run(){if(token!=generation)return;ArrayList<String> labels=new ArrayList<String>();for(File f:files)labels.add((favorites().contains(f.getAbsolutePath())?"★ ":"")+f.getName()+"\n"+android.text.format.DateFormat.format("dd.MM HH:mm",f.lastModified())+" · "+android.text.format.Formatter.formatShortFileSize(RecorderLibraryActivity.this,f.length()));list(L.t("Înregistrări Leo"),labels,0,new Choice(){public void pick(int n){actions(files.get(n));}},L.t("Filtre și căutare"),new Runnable(){public void run(){menu();}});}});}});}
 private void menu(){options(L.t("Înregistrări Leo"),new String[]{L.t("Toate"),L.t("Azi"),L.t("Ultimele 7 zile"),L.t("Favorite"),L.t("Caută T9 / text"),L.t("Triere · dată / nume")},new Choice(){public void pick(int n){if(n<4){filter=n;load();}else if(n==5){sort=1-sort;load();}else{LinearLayout f=fields(L.t("Caută înregistrări"));final EditText term=field(f,L.t("Nume sau cifre T9"),query,InputType.TYPE_CLASS_TEXT);left=new Runnable(){public void run(){query=term.getText().toString().trim();load();}};back=new Runnable(){public void run(){load();}};footer(L.t("Caută"),"Editor",L.t("Șterge"));term.requestFocus();}}});}
 private void actions(final File file){options(file.getName(),new String[]{L.t("Redă"),L.t("Adaugă / elimină favoritul"),L.t("Redenumește"),L.t("Partajează"),L.t("Șterge")},new Choice(){public void pick(int n){try{if(n==0){if(RecordingService.instance!=null){notice(L.t("Oprește înregistrarea întâi"));return;}startService(new Intent(RecorderLibraryActivity.this,PlaybackService.class).setData(LeoFileProvider.uri(RecorderLibraryActivity.this,file)).putExtra("title",file.getName()));startActivity(new Intent(RecorderLibraryActivity.this,MediaActivity.class).putExtra("now",true));}else if(n==1){Set<String> set=new HashSet<String>(favorites());String path=file.getCanonicalPath();if(!set.remove(path)){if(set.size()>=200)throw new IOException();set.add(path);}getSharedPreferences("recorder",0).edit().putStringSet("favorites",set).apply();load();}else if(n==3)ShareHubActivity.send(RecorderLibraryActivity.this,LeoFileProvider.uri(RecorderLibraryActivity.this,file),"audio/mp4",file.getName());else if(RecordingService.instance!=null)notice(L.t("Oprește înregistrarea întâi"));else if(n==2)rename(file);else options(L.t("Ștergi înregistrarea?"),new String[]{L.t("Păstrează"),L.t("Șterge")},new Choice(){public void pick(int yes){if(yes==1){if(!file.delete())notice(L.t("Ștergerea a eșuat"));else{Set<String> set=new HashSet<String>(favorites());set.remove(file.getAbsolutePath());getSharedPreferences("recorder",0).edit().putStringSet("favorites",set).apply();}load();}}});}catch(Exception e){notice(L.t("Fișier inaccesibil"));}}});}
 private void rename(final File file){LinearLayout f=fields(L.t("Nume înregistrare"));final EditText name=field(f,L.t("Nume · fără extensie"),file.getName().replaceFirst("\\.m4a$",""),InputType.TYPE_CLASS_TEXT);left=new Runnable(){public void run(){String value=name.getText().toString().trim();if(!RecorderProfile.validName(value)){notice(L.t("Nume invalid"));return;}File to=new File(file.getParentFile(),value+".m4a");if(to.exists()||!file.renameTo(to)){notice(L.t("Redenumirea a eșuat"));return;}Set<String> set=new HashSet<String>(favorites());if(set.remove(file.getAbsolutePath())){set.add(to.getAbsolutePath());getSharedPreferences("recorder",0).edit().putStringSet("favorites",set).apply();}load();}};back=new Runnable(){public void run(){load();}};footer(L.t("Salvează"),"Editor",L.t("Șterge"));name.requestFocus();}
}
